import { getLabelStackReference } from './index';
import { sanitizeLabelStackName } from './sanitize-label-stack-name';
export function optimizeLabelStack(labelStack, reactUFOVersion) {
  return reactUFOVersion === '2.0.0' ? getLabelStackReference(labelStack) : labelStack.map(ls => ({
    n: sanitizeLabelStackName(ls.name),
    ...(ls.segmentId ? {
      s: ls.segmentId
    } : {}),
    ...(ls.type ? {
      t: ls.type
    } : {})
  }));
}